DROP TABLE IF EXISTS `ai_models`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ai_models` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `provider_id` char(36) NOT NULL COMMENT 'FK to ai_providers',
  `model_id` varchar(100) NOT NULL COMMENT 'Model identifier from provider API',
  `name` varchar(255) NOT NULL COMMENT 'Display name',
  `description` text DEFAULT NULL,
  `context_window` int(11) NOT NULL DEFAULT 4000 COMMENT 'Max context tokens',
  `max_output_tokens` int(11) NOT NULL DEFAULT 2000 COMMENT 'Max tokens per request',
  `input_price_per_1k` decimal(10,6) NOT NULL DEFAULT 0.000000 COMMENT 'Price per 1000 input tokens',
  `output_price_per_1k` decimal(10,6) NOT NULL DEFAULT 0.000000 COMMENT 'Price per 1000 output tokens',
  `supports_vision` tinyint(1) NOT NULL DEFAULT 0,
  `supports_streaming` tinyint(1) NOT NULL DEFAULT 1,
  `supports_function_calling` tinyint(1) NOT NULL DEFAULT 0,
  `supports_tool_calling` tinyint(1) NOT NULL DEFAULT 0,
  `status` enum('active','inactive','beta','deprecated') NOT NULL DEFAULT 'active',
  `features` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Additional features as JSON object' CHECK (json_valid(`features`)),
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_provider` (`provider_id`),
  CONSTRAINT `fk_ai_models_provider` FOREIGN KEY (`provider_id`) REFERENCES `ai_providers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Available AI Models';
