DROP TABLE IF EXISTS `ai_notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ai_notifications` (
  `id` char(36) NOT NULL,
  `tenant_id` varchar(100) NOT NULL,
  `user_id` char(36) NOT NULL,
  `type` enum('overdue','deadline','daily_digest','revenue','custom') NOT NULL DEFAULT 'custom',
  `title` varchar(255) NOT NULL,
  `body` text NOT NULL,
  `action_label` varchar(100) DEFAULT NULL,
  `action_data` text DEFAULT NULL COMMENT 'JSON: {prompt: "..."} to send to AI chat',
  `read_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_user_unread` (`tenant_id`,`user_id`,`read_at`),
  KEY `idx_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

