CREATE TABLE `budget_items` (
  `id` char(36) NOT NULL,
  `tenant_id` char(36) NOT NULL,
  `project_id` char(36) NOT NULL,
  `task_id` char(36) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `description` text NOT NULL DEFAULT '',
  `category` enum('labor','material','equipment','travel','software','other','general') NOT NULL DEFAULT 'other',
  `planned_cost` decimal(15,2) NOT NULL DEFAULT 0.00,
  `actual_cost` decimal(15,2) NOT NULL DEFAULT 0.00,
  `quantity` decimal(10,2) NOT NULL DEFAULT 1.00,
  `unit_price` decimal(15,2) NOT NULL DEFAULT 0.00,
  `unit` varchar(50) NOT NULL DEFAULT 'unit',
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `vendor` varchar(255) NOT NULL DEFAULT '',
  `status` enum('planned','committed','actual','cancelled') NOT NULL DEFAULT 'planned',
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_budget_project` (`project_id`),
  KEY `idx_budget_task` (`task_id`),
  KEY `idx_budget_items_tenant` (`tenant_id`),
  CONSTRAINT `fk_budget_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_budget_task` FOREIGN KEY (`task_id`) REFERENCES `tasks` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
