--
-- Table structure for table `companies`
--

DROP TABLE IF EXISTS `companies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `companies` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `tenant_id` char(36) NOT NULL,
  `name` varchar(255) NOT NULL COMMENT 'Company name',
  `description` text DEFAULT '' COMMENT 'Company description',
  `address` text DEFAULT '' COMMENT 'Company address',
  `phone` varchar(50) DEFAULT '' COMMENT 'Company phone number',
  `email` varchar(255) DEFAULT '' COMMENT 'Company email',
  `website` varchar(255) DEFAULT '' COMMENT 'Company website URL',
  `tax_id` varchar(50) DEFAULT '' COMMENT 'Tax identification number',
  `logo_url` varchar(500) DEFAULT '' COMMENT 'Company logo URL',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Active status',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `business_type` varchar(100) DEFAULT NULL COMMENT 'Business type / industry',
  `company_type` enum('customer','partner','manufacturer') NOT NULL DEFAULT 'customer' COMMENT 'ประเภทบริษัท: customer=ลูกค้า, partner=คู่ค้า, manufacturer=ผู้ผลิต',
  `company_size` varchar(50) DEFAULT NULL COMMENT 'Company size range',
  `founded_year` smallint(4) DEFAULT NULL COMMENT 'Year company was founded',
  `tier` enum('partner','high_value','high_potential','transactional','low_volume') DEFAULT NULL COMMENT 'Customer tier classification',
  `tier_score` decimal(5,2) DEFAULT NULL COMMENT 'Classification confidence score (0-100)',
  `tier_updated_at` datetime DEFAULT NULL COMMENT 'Last tier classification timestamp',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_company_name` (`name`),
  KEY `idx_company_name` (`name`),
  KEY `idx_company_active` (`is_active`),
  KEY `idx_companies_tenant` (`tenant_id`),
  KEY `idx_companies_company_type` (`tenant_id`,`company_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Client companies';
/*!40101 SET character_set_client = @saved_cs_client */;

