DROP TABLE IF EXISTS `content_global_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `content_global_settings` (
  `tenant_id` varchar(100) NOT NULL,
  `global_instruction` text DEFAULT NULL,
  `image_gen_provider` varchar(50) NOT NULL DEFAULT 'none',
  `image_gen_api_key_encrypted` text DEFAULT NULL,
  `image_gen_model` varchar(100) DEFAULT NULL,
  `image_gen_base_url` varchar(500) DEFAULT NULL,
  `product_ref_image_url` text DEFAULT NULL COMMENT 'JSON array of product reference image URLs',
  `product_refs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of {name, url} product reference objects' CHECK (json_valid(`product_refs`)),
  `seo_gate_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `seo_gate_min_score` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `weekly_posts_target` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
