INSERT INTO `content_global_settings` VALUES ('tenant-default','ก่อนทำงานทุกครั้ง ให้อ่าน brand.md และ claude.md ของโปรเจคก่อนเสมอ จงปฏิบัติตามกฏ Do\'s & Don\'ts อย่างเครงครัด อย่าเพิ่มเนื้อหาที่ไม่ได้อยู่ใน Brand Identity','none',NULL,'','','[\"/uploads/product_ref/6a23ac7554bae_duckkit-ai-automate-ngansam-prahyadewla-30-chringhrueo.webp\",\"/uploads/product_ref/6a23cd74eb8d1_ktnbs_logo.png\",\"/uploads/product_ref/6a23cdaa3697e_IT_Outsource.jpg\",\"/uploads/product_ref/6a23e0cc4a2b1_duckkit_logo.png\",\"/uploads/product_ref/6a2560bb4fe86_Duckkit_Collaborate.png\"]','[{\"name\":\"Duckkit AI Portal\",\"url\":\"/uploads/product_ref/6a23ac7554bae_duckkit-ai-automate-ngansam-prahyadewla-30-chringhrueo.webp\",\"metadata\":{\"product_type\":\"AI dashboard / software platform\",\"primary_color\":\"#1a237e\",\"secondary_colors\":[\"#4fc3f7\",\"#ff6d00\"],\"shape_description\":\"Rectangular dashboard panel with rounded cards and floating UI elements\",\"texture_style\":\"Flat vector illustration with subtle gradients\",\"key_elements\":[\"Duck mascot\",\"AI provider icons\",\"Cost analytics charts\",\"Security shield\",\"Automation workflow\"],\"composition\":\"Centered dashboard with surrounding floating UI cards\",\"mood\":\"Professional and innovative\",\"category\":\"AI, dashboard, automation, SaaS, platform\"}},{\"name\":\"KTNBS Logo\",\"url\":\"/uploads/product_ref/6a23cd74eb8d1_ktnbs_logo.png\",\"metadata\":null},{\"name\":\"IT Outsource\",\"url\":\"/uploads/product_ref/6a23cdaa3697e_IT_Outsource.jpg\",\"metadata\":null},{\"name\":\"duckkit logo\",\"url\":\"/uploads/product_ref/6a23e0cc4a2b1_duckkit_logo.png\",\"metadata\":{\"raw_analysis\":\"{\\n  \\\"product_type\\\": \\\"3D mascot/character figurine (digital 3D render of a rubber duck wearing headphones)\\\",\\n  \\\"primary_color\\\": \\\"#F4FAFF\\\",\\n  \\\"secondary_colors\\\": [\\\"#FFCC33\\\", \\\"#1C1C1F\\\", \\\"#2A3B9F\\\"],\\n  \\\"shape_description\\\": \\\"Chubby rounded duck shape with a spherical body, circular head, short rounded wings and a protruding beak.\\\",\\n  \\\"texture_style\\\": \\\"Soft 3D render with smooth matte plastic surface and subtle glossy highlights on eyes and beak\\\",\\n  \\\"key_elements\\\": [\\\"white rounded duck body\\\", \\\"yellow beak\\\", \\\"black over-ear headphones\\\", \\\"small glossy dark eyes\\\", \\\"raised wings\\\"],\\n  \\\"composition\\\": \\\"Centered single-subject composition on an isolated background, three-quarter frontal view with symmetrical balance\\\",\\n  \\\"mood\\\": \\\"playful, friendly\\\",\\n  \\\"\"},\"analyzing\":false},{\"name\":\"Duckkit Collaborate\",\"url\":\"/uploads/product_ref/6a2560bb4fe86_Duckkit_Collaborate.png\",\"metadata\":{\"raw_analysis\":\"AI analysis failed\"},\"analyzing\":false}]',0,0,0,'2026-05-03 19:04:49','2026-06-07 19:15:13');
