DROP TABLE IF EXISTS `content_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `content_items` (
  `id` char(36) NOT NULL,
  `tenant_id` char(36) NOT NULL,
  `title` varchar(500) NOT NULL,
  `type` enum('article','image','video') NOT NULL DEFAULT 'article',
  `status` enum('published','draft','revision','pending_approval','rejected','approved') NOT NULL DEFAULT 'draft',
  `reject_reason` text DEFAULT NULL,
  `requested_at` datetime DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `published_url` varchar(1000) DEFAULT NULL,
  `external_post_id` varchar(255) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `views` int(11) NOT NULL DEFAULT 0,
  `likes` int(11) NOT NULL DEFAULT 0,
  `created_by` char(36) NOT NULL,
  `plan_item_id` char(36) DEFAULT NULL,
  `platform` varchar(100) DEFAULT NULL,
  `scheduled_date` date DEFAULT NULL,
  `scheduled_at` datetime DEFAULT NULL,
  `caption` longtext DEFAULT NULL,
  `image_brief` longtext DEFAULT NULL,
  `generated_image_url` varchar(1000) DEFAULT NULL,
  `image_gen_status` enum('none','generating','done','failed') NOT NULL DEFAULT 'none',
  `video_gen_status` enum('none','generating','done','failed') NOT NULL DEFAULT 'none' COMMENT 'Video generation job state',
  `video_url` varchar(1000) DEFAULT NULL COMMENT 'URL to generated video file',
  `video_job_id` varchar(255) DEFAULT NULL COMMENT 'Async job ID from video provider for polling',
  `article_content` longtext DEFAULT NULL,
  `seo_title` varchar(200) DEFAULT NULL,
  `slug` varchar(300) DEFAULT NULL,
  `meta_description` varchar(320) DEFAULT NULL,
  `meta_keywords` varchar(500) DEFAULT NULL,
  `structured_data` longtext DEFAULT NULL,
  `og_image` varchar(1000) DEFAULT NULL,
  `plan_id` char(36) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_content_items_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

