\u0e27\\u0e32\\u0e21\\u0e25\\u0e31\\u0e1a\\u0e02\\u0e2d\\u0e07\\u0e25\\u0e39\\u0e01\\u0e04\\u0e49\\u0e32\\u0e23\\u0e31\\u0e48\\u0e27\\u0e44\\u0e2b\\u0e25 (Data Leakage) \\u0e23\\u0e27\\u0e21\\u0e16\\u0e36\\u0e07\\u0e04\\u0e48\\u0e32\\u0e43\\u0e0a\\u0e49\\u0e08\\u0e48\\u0e32\\u0e22\\u0e43\\u0e19\\u0e01\\u0e32\\u0e23\\u0e0b\\u0e37\\u0e49\\u0e2d\\u0e44\\u0e25\\u0e40\\u0e0b\\u0e19\\u0e2a\\u0e4c\\u0e0b\\u0e2d\\u0e1f\\u0e15\\u0e4c\\u0e41\\u0e27\\u0e23\\u0e4c\\u0e41\\u0e22\\u0e01\\u0e23\\u0e32\\u0e22\\u0e1a\\u0e38\\u0e04\\u0e04\\u0e25\\u0e02\\u0e2d\\u0e07\\u0e41\\u0e15\\u0e48\\u0e01\\u0e25\\u0e38\\u0e48\\u0e21\\u0e40\\u0e04\\u0e23\\u0e37\\u0e48\\u0e2d\\u0e07\\u0e21\\u0e37\\u0e2d (\\u0e40\\u0e0a\\u0e48\\u0e19 ChatGPT Plus, Claude Pro, Gemini Advanced) \\u0e17\\u0e35\\u0e48\\u0e1a\\u0e32\\u0e19\\u0e1b\\u0e25\\u0e32\\u0e22\\u0e41\\u0e25\\u0e30\\u0e22\\u0e32\\u0e01\\u0e15\\u0e48\\u0e2d\\u0e01\\u0e32\\u0e23\\u0e04\\u0e27\\u0e1a\\u0e04\\u0e38\\u0e21<\\/p>\\n<p><strong>KTN Business Solutions (KTNBS)<\\/strong> \\u0e43\\u0e19\\u0e10\\u0e32\\u0e19\\u0e30\\u0e2a\\u0e16\\u0e32\\u0e1b\\u0e19\\u0e34\\u0e01\\u0e23\\u0e30\\u0e1a\\u0e1a\\u0e04\\u0e39\\u0e48\\u0e04\\u0e34\\u0e14\\u0e02\\u0e2d\\u0e07\\u0e04\\u0e38\\u0e13 (System Architect &amp; Strategic Partner) \\u0e17\\u0e35\\u0e48\\u0e40\\u0e02\\u0e49\\u0e32\\u0e43\\u0e08\\u0e1a\\u0e23\\u0e34\\u0e1a\\u0e17\\u0e01\\u0e32\\u0e23\\u0e17\\u0e33\\u0e07\\u0e32\\u0e19\\u0e02\\u0e2d\\u0e07\\u0e18\\u0e38\\u0e23\\u0e01\\u0e34\\u0e08\\u0e44\\u0e17\\u0e22\\u0e2d\\u0e22\\u0e48\\u0e32\\u0e07\\u0e41\\u0e17\\u0e49\\u0e08\\u0e23\\u0e34\\u0e07 \\u0e44\\u0e14\\u0e49\\u0e1e\\u0e31\\u0e12\\u0e19\\u0e32 <strong>Duckkit (AI Portal)<\\/strong> \\u0e41\\u0e1e\\u0e25\\u0e15\\u0e1f\\u0e2d\\u0e23\\u0e4c\\u0e21\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c\\u0e01\\u0e25\\u0e32\\u0e07\\u0e14\\u0e49\\u0e32\\u0e19 AI \\u0e17\\u0e35\\u0e48\\u0e2d\\u0e2d\\u0e01\\u0e41\\u0e1a\\u0e1a\\u0e21\\u0e32\\u0e40\\u0e1e\\u0e37\\u0e48\\u0e2d\\u0e17\\u0e25\\u0e32\\u0e22\\u0e2d\\u0e38\\u0e1b\\u0e2a\\u0e23\\u0e23\\u0e04\\u0e40\\u0e2b\\u0e25\\u0e48\\u0e32\\u0e19\\u0e35\\u0e49 \\u0e0a\\u0e48\\u0e27\\u0e22\\u0e04\\u0e27\\u0e1a\\u0e04\\u0e38\\u0e21\\u0e17\\u0e31\\u0e49\\u0e07\\u0e07\\u0e1a\\u0e1b\\u0e23\\u0e30\\u0e21\\u0e32\\u0e13 \\u0e04\\u0e27\\u0e32\\u0e21\\u0e1b\\u0e25\\u0e2d\\u0e14\\u0e20\\u0e31\\u0e22 \\u0e41\\u0e25\\u0e30\\u0e1b\\u0e23\\u0e30\\u0e2a\\u0e34\\u0e17\\u0e18\\u0e34\\u0e1c\\u0e25\\u0e01\\u0e32\\u0e23\\u0e17\\u0e33\\u0e07\\u0e32\\u0e19 (Productivity) \\u0e43\\u0e2b\\u0e49\\u0e01\\u0e31\\u0e1a\\u0e17\\u0e38\\u0e01\\u0e17\\u0e35\\u0e21\\u0e43\\u0e19\\u0e2d\\u0e07\\u0e04\\u0e4c\\u0e01\\u0e23\\u0e02\\u0e2d\\u0e07\\u0e04\\u0e38\\u0e13<\\/p>\\n\\n<h2>Duckkit \\u0e04\\u0e37\\u0e2d\\u0e2d\\u0e30\\u0e44\\u0e23? \\u0e17\\u0e33\\u0e04\\u0e27\\u0e32\\u0e21\\u0e23\\u0e39\\u0e49\\u0e08\\u0e31\\u0e01\\u0e41\\u0e1e\\u0e25\\u0e15\\u0e1f\\u0e2d\\u0e23\\u0e4c\\u0e21\\u0e08\\u0e31\\u0e14\\u0e01\\u0e32\\u0e23 AI \\u0e41\\u0e1a\\u0e1a\\u0e23\\u0e27\\u0e21\\u0e28\\u0e39\\u0e19\\u0e22\\u0e4c<\\/h2>\\n<p>Duckkit \\u0e04\\u0e37\\u0e2d AI Portal \\u0e23\\u0e30\\u0e14\\u0e31\\u0e1a\\u0e2d\\u0e07\\u0e04\\u0e4c\\u0e01\\u0e23\\u0e17\\u0e35\\u0e48\\u0e40\\u0e1b\\u0e23\\u0e35\\u0e22\\u0e1a\\u0e40\\u0e2a\\u0e21\\u0e37\\u0e2d\\u0e19\\u0e2a\\u0e30\\u0e1e\\u0e32\\u0e19\\u0e40\\u0e0a\\u0e37\\u0e48\\u0e2d\\u0e21\\u0e17\\u0e35\\u0e48\\u0e1b\\u0e25\\u0e2d\\u0e14\\u0e20\\u0e31\\u0e22\\u0e23\\u0e30\\u0e2b\\u0e27\\u0e48\\u0e32\\u0e07\\u0e1e\\u0e19\\u0e31\\u0e01\\u0e07\\u0e32\\u0e19\\u0e01\\u0e31\\u0e1a\\u0e02\\u0e38\\u0e21\\u0e1e\\u0e25\\u0e31\\u0e07\\u0e1b\\u0e31\\u0e0d\\u0e0d\\u0e32\\u0e1b\\u0e23\\u0e30\\u0e14\\u0e34\\u0e29\\u0e10\\u0e4c\\u0e23\\u0e30\\u0e14\\u0e31\\u0e1a\\u0e42\\u0e25\\u0e01 \\u0e41\\u0e17\\u0e19\\u0e17\\u0e35\\u0e48\\u0e08\\u0e30\\u0e1b\\u0e25\\u0e48\\u0e2d\\u0e22\\u0e43\\u0e2b\\u0e49\\u0e1e\\u0e19\\u0e31\\u0e01\\u0e07\\u0e32\\u0e19\\u0e2a\\u0e21\\u0e31\\u0e04\\u0e23\\u0e1a\\u0e31\\u0e0d\\u0e0a\\u0e35\\u0e2a\\u0e48\\u0e27\\u0e19\\u0e15\\u0e31\\u0e27\\u0e41\\u0e25\\u0e30\\u0e43\\u0e0a\\u0e49\\u0e1a\\u0e31\\u0e15\\u0e23\\u0e40\\u0e04\\u0e23\\u0e14\\u0e34\\u0e15\\u0e2a\\u0e48\\u0e27\\u0e19\\u0e15\\u0e31\\u0e27\\u0e40\\u0e1a\\u0e34\\u0e01\\u0e40\\u0e07\\u0e34\\u0e19 \\u0e0b\\u0e36\\u0e48\\u0e07\\u0e40\\u0e2a\\u0e35\\u0e48\\u0e22\\u0e07\\u0e15\\u0e48\\u0e2d\\u0e01\\u0e32\\u0e23\\u0e19\\u0e33\\u0e02\\u0e49\\u0e2d\\u0e21\\u0e39\\u0e25\\u0e20\\u0e32\\u0e22\\u0e43\\u0e19\\u0e44\\u0e1b\\u0e40\\u0e17\\u0e23\\u0e19 AI \\u0e2a\\u0e32\\u0e18\\u0e32\\u0e23\\u0e13\\u0e30 Duckkit \\u0e08\\u0e30\\u0e17\\u0e33\\u0e2b\\u0e19\\u0e49\\u0e32\\u0e17\\u0e35\\u0e48\\u0e40\\u0e1b\\u0e47\\u0e19\\u0e40\\u0e01\\u0e15\\u0e40\\u0e27\\u0e22\\u0e4c\\u0e15\\u0e31\\u0e27\\u0e01\\u0e25\\u0e32\\u0e07\\u0e17\\u0e35\\u0e48\\u0e23\\u0e27\\u0e21\\u0e40\\u0e2d\\u0e32\\u0e42\\u0e21\\u0e40\\u0e14\\u0e25\\u0e15\\u0e31\\u0e27\\u0e17\\u0e47\\u0e2d\\u0e1b\\u0e2d\\u0e22\\u0e48\\u0e32\\u0e07 OpenAI (GPT-4), Anthropic (Claude) \\u0e41\\u0e25\\u0e30 Google (Gemini) \\u0e21\\u0e32\\u0e23\\u0e27\\u0e21\\u0e44\\u0e27\\u0e49\\u0e43\\u0e19\\u0e17\\u0e35\\u0e48\\u0e43\\u0e0a\\u0e49\\u0e07\\u0e32\\u0e19\\u0e08\\u0e38\\u0e14\\u0e40\\u0e14\\u0e35\\u0e22\\u0e27\\u0e20\\u0e32\\u0e22\\u0e43\\u0e15\\u0e49\\u0e01\\u0e32\\u0e23\\u0e1a\\u0e23\\u0e34\\u0e2b\\u0e32\\u0e23\\u0e08\\u0e31\\u0e14\\u0e01\\u0e32\\u0e23\\u0e02\\u0e2d\\u0e07\\u0e1d\\u0e48\\u0e32\\u0e22\\u0e44\\u0e2d\\u0e17\\u0e35\\u0e02\\u0e2d\\u0e07\\u0e2d\\u0e07\\u0e04\\u0e4c\\u0e01\\u0e23<\\/p>\\n\\n<h2>3 \\u0e08\\u0e38\\u0e14\\u0e40\\u0e14\\u0e48\\u0e19\\u0e2a\\u0e33\\u0e04\\u0e31\\u0e0d\\u0e17\\u0e35\\u0e48\\u0e17\\u0e33\\u0e43\\u0e2b\\u0e49 Duckkit \\u0e41\\u0e15\\u0e01\\u0e15\\u0e48\\u0e32\\u0e07\\u0e41\\u0e25\\u0e30\\u0e15\\u0e2d\\u0e1a\\u0e42\\u0e08\\u0e17\\u0e22\\u0e4c\\u0e18\\u0e38\\u0e23\\u0e01\\u0e34\\u0e08\\u0e08\\u0e23\\u0e34\\u0e07<\\/h2>\\n<h3>1. Enterprise Security &amp; Data Governance (\\u0e04\\u0e27\\u0e32\\u0e21\\u0e1b\\u0e25\\u0e2d\\u0e14\\u0e20\\u0e31\\u0e22\\u0e2a\\u0e39\\u0e07\\u0e2a\\u0e38\\u0e14\\u0e2a\\u0e33\\u0e2b\\u0e23\\u0e31\\u0e1a\\u0e02\\u0e49\\u0e2d\\u0e21\\u0e39\\u0e25\\u0e23\\u0e30\\u0e14\\u0e31\\u0e1a\\u0e2d\\u0e07\\u0e04\\u0e4c\\u0e01\\u0e23)<\\/h3>\\n<p>\\u0e14\\u0e49\\u0e27\\u0e22\\u0e23\\u0e30\\u0e1a\\u0e1a\\u0e23\\u0e31\\u0e01\\u0e29\\u0e32\\u0e04\\u0e27\\u0e32\\u0e21\\u0e1b\\u0e25\\u0e2d\\u0e14\\u0e20\\u0e31\\u0e22\\u0e20\\u0e32\\u0e22\\u0e43\\u0e15\\u0e49\\u0e21\\u0e32\\u0e15\\u0e23\\u0e10\\u0e32\\u0e19\\u0e2a\\u0e32\\u0e01\\u0e25 Duckkit \\u0e0a\\u0e48\\u0e27\\u0e22\\u0e25\\u0e47\\u0e2d\\u0e01\\u0e01\\u0e32\\u0e23\\u0e44\\u0e2b\\u0e25\\u0e40\\u0e02\\u0e49\\u0e32\\u0e2d\\u0e2d\\u0e01\\u0e02\\u0e2d\\u0e07\\u0e02\\u0e49\\u0e2d\\u0e21\\u0e39\\u0e25\\u0e2d\\u0e22\\u0e48\\u0e32\\u0e07\\u0e40\\u0e02\\u0e49\\u0e21\\u0e07\\u0e27\\u0e14 \\u0e21\\u0e31\\u0e48\\u0e19\\u0e43\\u0e08\\u0e44\\u0e14\\u0e49\\u0e27\\u0e48\\u0e32\\u0e02\\u0e49\\u0e2d\\u0e21\\u0e39\\u0e25\\u0e41\\u0e0a\\u0e17 \\u0e40\\u0e2d\\u0e01\\u0e2a\\u0e32\\u0e23\\u0e2a\\u0e31\\u0e0d\\u0e0d\\u0e32 \\u0e2a\\u0e39\\u0e15\\u0e23\\u0e04\\u0e33\\u0e19\\u0e27\\u0e13 \\u0e2b\\u0e23\\u0e37\\u0e2d Source Code \\u0e17\\u0e35\\u0e48\\u0e1e\\u0e19\\u0e31\\u0e01\\u0e07\\u0e32\\u0e19\\u0e2d\\u0e31\\u0e1b\\u0e42\\u0e2b\\u0e25\\u0e14\\u0e40\\u0e02\\u0e49\\u0e32\\u0e44\\u0e1b\\u0e40\\u0e1e\\u0e37\\u0e48\\u0e2d\\u0e2a\\u0e48\\u0e07\\u0e43\\u0e2b\\u0e49 AI \\u0e0a\\u0e48\\u0e27\\u0e22\\u0e1b\\u0e23\\u0e30\\u0e40\\u0e21\\u0e34\\u0e19\\u0e1c\\u0e25 \\u0e08\\u0e30\\u0e44\\u0e21\\u0e48\\u0e16\\u0e39\\u0e01\\u0e04\\u0e48\\u0e32\\u0e22\\u0e22\\u0e31\\u0e01\\u0e29\\u0e4c\\u0e43\\u0e2b\\u0e0d\\u0e48\\u0e14\\u0e36\\u0e07\\u0e22\\u0e49\\u0e2d\\u0e19\\u0e01\\u0e25\\u0e31\\u0e1a\\u0e44\\u0e1b\\u0e43\\u0e0a\\u0e49\\u0e40\\u0e1b\\u0e47\\u0e19\\u0e02\\u0e49\\u0e2d\\u0e21\\u0e39\\u0e25\\u0e1d\\u0e36\\u0e01\\u0e1d\\u0e19\\u0e42\\u0e21\\u0e40\\u0e14\\u0e25 (Training Data) \\u0e0b\\u0e36\\u0e48\\u0e07\\u0e40\\u0e1b\\u0e47\\u0e19\\u0e2b\\u0e31\\u0e27\\u0e43\\u0e08\\u0e2a\\u0e33\\u0e04\\u0e31\\u0e0d\\u0e02\\u0e2d\\u0e07\\u0e01\\u0e32\\u0e23\\u0e17\\u0e33 AI Governance \\u0e43\\u0e19\\u0e2d\\u0e07\\u0e04\\u0e4c\\u0e01\\u0e23<\\/p>\\n<h3>2. Cost Control Dashboard (\\u0e04\\u0e27\\u0e1a\\u0e04\\u0e38\\u0e21\\u0e07\\u0e1a\\u0e1b\\u0e23\\u0e30\\u0e21\\u0e32\\u0e13\\u0e04\\u0e48\\u0e32\\u0e1a\\u0e23\\u0e34\\u0e01\\u0e32\\u0e23 AI \\u0e44\\u0e14\\u0e49\\u0e23\\u0e32\\u0e22\\u0e2b\\u0e31\\u0e27\\u0e41\\u0e25\\u0e30\\u0e23\\u0e32\\u0e22\\u0e41\\u0e1c\\u0e19\\u0e01)<\\/h3>\\n<p>\\u0e2b\\u0e21\\u0e14\\u0e1b\\u0e31\\u0e0d\\u0e2b\\u0e32\\u0e23\\u0e32\\u0e22\\u0e0a\\u0e48\\u0e32\\u0e22\\u0e1a\\u0e32\\u0e19\\u0e1b\\u0e25\\u0e32\\u0e22\\u0e08\\u0e32\\u0e01\\u0e01\\u0e32\\u0e23\\u0e2a\\u0e21\\u0e31\\u0e04\\u0e23\\u0e04\\u0e48\\u0e32\\u0e1a\\u0e23\\u0e34\\u0e01\\u0e32\\u0e23\\u0e23\\u0e32\\u0e22\\u0e40\\u0e14\\u0e37\\u0e2d\\u0e19\\u0e41\\u0e1a\\u0e1a\\u0e40\\u0e2b\\u0e21\\u0e32\\u0e41\\u0e22\\u0e01\\u0e04\\u0e48\\u0e32\\u0e22 Duckkit \\u0e21\\u0e32\\u0e1e\\u0e23\\u0e49\\u0e2d\\u0e21\\u0e23\\u0e30\\u0e1a\\u0e1a\\u0e41\\u0e14\\u0e0a\\u0e1a\\u0e2d\\u0e23\\u0e4c\\u0e14\\u0e08\\u0e31\\u0e14\\u0e01\\u0e32\\u0e23\\u0e07\\u0e1a\\u0e1b\\u0e23\\u0e30\\u0e21\\u0e32\\u0e13\\u0e04\\u0e48\\u0e32\\u0e43\\u0e0a\\u0e49\\u0e07\\u0e32\\u0e19 API \\u0e17\\u0e35\\u0e48\\u0e04\\u0e23\\u0e2d\\u0e1a\\u0e04\\u0e25\\u0e38\\u0e21\\u0e41\\u0e1a\\u0e1a\\u0e40\\u0e23\\u0e35\\u0e22\\u0e25\\u0e44\\u0e17\\u0e21\\u0e4c \\u0e1c\\u0e39\\u0e49\\u0e14\\u0e39\\u0e41\\u0e25\\u0e23\\u0e30\\u0e1a\\u0e1a\\u0e2a\\u0e32\\u0e21\\u0e32\\u0e23\\u0e16\\u0e01\\u0e33\\u0e2b\\u0e19\\u0e14 Budget Limit \\u0e23\\u0e32\\u0e22\\u0e04\\u0e19 \\u0e23\\u0e32\\u0e22\\u0e41\\u0e1c\\u0e19\\u0e01 \\u0e2b\\u0e23\\u0e37\\u0e2d\\u0e08\\u0e33\\u0e01\\u0e31\\u0e14\\u0e01\\u0e32\\u0e23\\u0e43\\u0e0a\\u0e49\\u0e07\\u0e32\\u0e19\\u0e15\\u0e32\\u0e21\\u0e04\\u0e27\\u0e32\\u0e21\\u0e08\\u0e33\\u0e40\\u0e1b\\u0e47\\u0e19\\u0e44\\u0e14\\u0e49\\u0e08\\u0e23\\u0e34\\u0e07 \\u0e0a\\u0e48\\u0e27\\u0e22\\u0e40\\u0e1b\\u0e25\\u0e35\\u0e48\\u0e22\\u0e19\\u0e15\\u0e49\\u0e19\\u0e17\\u0e38\\u0e19\\u0e