DROP TABLE IF EXISTS `content_schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `content_schedules` (
  `id` char(36) NOT NULL,
  `plan_item_id` char(36) NOT NULL,
  `channel_id` char(36) NOT NULL,
  `scheduled_at` datetime NOT NULL,
  `status` enum('pending','publishing','sent','failed') NOT NULL DEFAULT 'pending',
  `retry_count` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `next_retry_at` datetime DEFAULT NULL,
  `publish_result` longtext DEFAULT NULL,
  `platform_post_id` varchar(255) DEFAULT NULL,
  `published_url` varchar(1000) DEFAULT NULL,
  `created_by` char(36) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_item` (`plan_item_id`),
  KEY `idx_channel` (`channel_id`),
  KEY `idx_content_schedules_retry` (`status`,`next_retry_at`,`scheduled_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

