INSERT INTO `cron_jobs` VALUES ('2d450423-a2a3-11f1-8f21-088fc3692a3e','content-metrics-sync','Content Metrics Sync','ระบุรายละเอียดของข้อมูลหรือสถิติที่ต้องการเก็บ เช่น views/likes ของโพสต์จากแพลตฟอร์มต่าง ๆ (Facebook/Instagram) โดยข้อมูลจะถูกจัดเก็บใน content_post_metrics และสามารถนำไปใช้สำหรับแสดงข้อมูลแบบ time-series ในแดชบอร์ดหรือรายงานของระบบ โดยอ้างอิงข้อมูลจาก content_items','ทุก 6 ชั่วโมง','0 */6 * * *',NULL,'2026-08-28 18:00:00','include','','api/cron/content-metrics-sync.php','GET','',1,'2026-08-28 12:41:54','2026-08-28 13:22:57'),('ae589687-6342-11f1-8e35-b4a9fcd19bae','cron-publish','Content Publish Scheduler','ประมวลผล content_schedules ที่ถึงเวลาโพสต์ (brand-content flow)','ทุก 1 นาที','* * * * *',NULL,NULL,'http','cron-publish.php',NULL,'GET',NULL,0,'2026-06-08 21:02:21','2026-08-28 12:41:55'),('ae58b40b-6342-11f1-8e35-b4a9fcd19bae','publish-scheduler','Publish Queue Processor','ประมวลผล content_publish_queue (SchedulePublishDialog flow)','ทุก 1 นาที','* * * * *','2026-08-28 17:02:01','2026-08-28 17:03:00','include',NULL,'api/cron/publish-scheduler.php','GET',NULL,1,'2026-06-08 21:02:21','2026-08-28 17:02:01'),('ae58b504-6342-11f1-8e35-b4a9fcd19bae','notification-dispatch','Notification Dispatch','ส่งการแจ้งเตือนผ่าน Line OA, Telegram, Email','ทุก 15 นาที','*/15 * * * *',NULL,NULL,'http','notification-dispatch.php',NULL,'GET',NULL,0,'2026-06-08 21:02:21','2026-08-28 12:41:55'),('ae58b54e-6342-11f1-8e35-b4a9fcd19bae','recurring-tasks','Recurring Task Generator','สร้าง instance ของงานซ้ำที่ถึงกำหนด','ทุกวัน เที่ยงคืน','0 0 * * *',NULL,NULL,'http','recurring-tasks.php',NULL,'POST','trigger=1',0,'2026-06-08 21:02:21','2026-08-28 12:41:55'),('c5336923-6663-11f1-9e48-b4a9fcd19bae','ai-digest','AI Daily Digest','สร้าง ai_notifications สำหรับงานเกินกำหนดและ deadline วันนี้ ทุก user','ทุกวัน 07:30','30 7 * * *',NULL,'2026-08-29 07:30:00','include',NULL,'api/cron/ai-digest.php','GET',NULL,1,'2026-06-12 20:36:23','2026-08-28 12:42:01'),('c537cc5d-6663-11f1-9e48-b4a9fcd19bae','billing-reminders','Billing Reminders','ตรวจสอบ subscription ที่ใกล้หมดอายุและส่ง email แจ้งเตือน admin','ทุกวัน 09:00','0 9 * * *',NULL,NULL,'include',NULL,'api/cron/billing-reminders.php','GET',NULL,0,'2026-06-12 20:36:23','2026-08-28 12:41:55');
