--
-- Table structure for table `custom_fields`
--

DROP TABLE IF EXISTS `custom_fields`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `custom_fields` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `tenant_id` char(36) NOT NULL,
  `name` varchar(100) NOT NULL COMMENT 'Field name',
  `field_type` enum('text','number','date','select','multiselect','currency','boolean') NOT NULL DEFAULT 'text' COMMENT 'Type of field',
  `field_options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Options for select/multiselect fields' CHECK (json_valid(`field_options`)),
  `default_value` varchar(255) DEFAULT NULL COMMENT 'Default value',
  `is_required` tinyint(1) DEFAULT 0 COMMENT 'Is field required?',
  `is_global` tinyint(1) DEFAULT 1 COMMENT 'Is global (usable in all projects)?',
  `visibility` enum('public','private','admin') DEFAULT 'public' COMMENT 'Who can see this field',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_custom_fields_name` (`name`),
