--
-- Table structure for table `customers`
--

DROP TABLE IF EXISTS `customers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customers` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `tenant_id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL COMMENT 'Parent company',
  `first_name` varchar(100) NOT NULL COMMENT 'First name',
  `last_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Last name',
  `email` varchar(255) NOT NULL DEFAULT '' COMMENT 'Customer email',
  `phone` varchar(50) DEFAULT '' COMMENT 'Customer phone',
  `position` varchar(100) DEFAULT '' COMMENT 'Job position',
  `is_primary_contact` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Is primary contact for company',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Active status',
  `notes` text DEFAULT '' COMMENT 'Additional notes',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_customer_company_email` (`company_id`,`email`(191)),
  KEY `idx_customer_company` (`company_id`),
  KEY `idx_customer_email` (`email`),
  KEY `idx_customer_primary` (`is_primary_contact`),
  KEY `idx_customer_active` (`is_active`),
  KEY `idx_customers_tenant` (`tenant_id`),
  CONSTRAINT `fk_customers_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Customer contacts for companies';
/*!40101 SET character_set_client = @saved_cs_client */;

