DROP TABLE IF EXISTS `goal_tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `goal_tasks` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `goal_id` char(36) NOT NULL COMMENT 'Goal ID',
  `task_id` char(36) NOT NULL COMMENT 'Task ID',
  `contribution_percentage` decimal(5,2) DEFAULT 100.00 COMMENT 'How much this task contributes to goal',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_goal_task_unique` (`goal_id`,`task_id`),
  KEY `idx_goal_task_goal` (`goal_id`),
  KEY `idx_goal_task_task` (`task_id`),
  CONSTRAINT `fk_goal_task_goal` FOREIGN KEY (`goal_id`) REFERENCES `goals` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_goal_task_task` FOREIGN KEY (`task_id`) REFERENCES `tasks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Link between goals and tasks';
