DROP TABLE IF EXISTS `goals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `goals` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `tenant_id` char(36) NOT NULL,
  `parent_goal_id` char(36) DEFAULT NULL COMMENT 'Parent goal for hierarchy',
  `project_id` char(36) DEFAULT NULL,
  `company_id` char(36) DEFAULT NULL,
  `title` varchar(255) NOT NULL COMMENT 'Goal title',
  `description` text DEFAULT NULL COMMENT 'Goal description',
  `goal_type` enum('objective','key_result','kpi','milestone','company','department','project','personal') NOT NULL DEFAULT 'objective',
  `target_value` decimal(15,2) DEFAULT NULL COMMENT 'Target value',
  `current_value` decimal(15,2) DEFAULT 0.00 COMMENT 'Current progress value',
  `progress_percentage` decimal(5,2) NOT NULL DEFAULT 0.00,
  `unit` varchar(50) DEFAULT NULL COMMENT 'Unit of measurement (%, count, currency, etc.)',
  `start_date` date NOT NULL COMMENT 'Goal start date',
  `end_date` date NOT NULL COMMENT 'Goal end date',
  `status` enum('draft','active','completed','cancelled','at_risk','on_hold') NOT NULL DEFAULT 'active',
  `weight` decimal(5,2) DEFAULT 1.00 COMMENT 'Weight for overall calculation',
  `created_by` char(36) NOT NULL COMMENT 'User who created the goal',
  `owner_id` char(36) DEFAULT NULL COMMENT 'User responsible for this goal',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_goals_parent` (`parent_goal_id`),
  KEY `idx_goals_type` (`goal_type`),
  KEY `idx_goals_status` (`status`),
  KEY `idx_goals_dates` (`start_date`,`end_date`),
  KEY `idx_goals_tenant` (`tenant_id`),
  CONSTRAINT `fk_goals_parent` FOREIGN KEY (`parent_goal_id`) REFERENCES `goals` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Goals and OKR/KPI tracking';
/*!40101 SET character_set_client = @saved_cs_client */;

