DROP TABLE IF EXISTS `inbox_messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inbox_messages` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `tenant_id` char(36) NOT NULL,
  `user_id` char(36) NOT NULL COMMENT 'FK to users - recipient',
  `sender_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Sender display name',
  `sender_email` varchar(255) NOT NULL DEFAULT '' COMMENT 'Sender email',
  `subject` varchar(500) NOT NULL DEFAULT '' COMMENT 'Message subject',
  `preview` text DEFAULT NULL COMMENT 'Message preview/text',
  `type` enum('ticket','message','notification','email') NOT NULL DEFAULT 'message' COMMENT 'Message type',
  `is_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=unread, 1=read',
  `is_starred` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=not starred, 1=starred',
  `priority` enum('low','medium','high','critical') NOT NULL DEFAULT 'medium',
  `status` varchar(50) NOT NULL DEFAULT 'open' COMMENT 'Status for tickets',
  `related_id` char(36) DEFAULT NULL COMMENT 'Related item ID (ticket, project, etc.)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_inbox_user` (`user_id`),
  KEY `idx_inbox_read` (`is_read`),
  KEY `idx_inbox_type` (`type`),
  KEY `idx_inbox_created` (`created_at`),
  KEY `idx_inbox_messages_tenant` (`tenant_id`),
  CONSTRAINT `fk_inbox_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Inbox messages for users';
