--
-- Table structure for table `projects`
--

DROP TABLE IF EXISTS `projects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `projects` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `tenant_id` char(36) NOT NULL,
  `user_id` char(36) NOT NULL COMMENT 'Project owner',
  `manager_id` char(36) DEFAULT NULL,
  `company_id` char(36) DEFAULT NULL COMMENT 'Client company',
  `opportunity_id` char(36) DEFAULT NULL,
  `customer_id` char(36) DEFAULT NULL COMMENT 'Primary customer contact',
  `name` varchar(255) NOT NULL COMMENT 'Project name',
  `description` text NOT NULL DEFAULT '' COMMENT 'Project description',
  `kind` enum('project','base_calendar') NOT NULL DEFAULT 'project' COMMENT 'project = งานของลูกค้า, base_calendar = ปฏิทินทีมส่วนกลาง (ห้ามลบ)',
  `is_protected` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'ห้ามลบ (เช่น Base Calendar)',
  `status` enum('on-track','at-risk','delayed','completed','cancelled') NOT NULL DEFAULT 'on-track',
  `start_date` date NOT NULL DEFAULT curdate() COMMENT 'Project start date',
  `end_date` date NOT NULL COMMENT 'Project deadline',
  `original_end_date` date DEFAULT NULL COMMENT 'Original deadline (before extension)',
  `extension_reason` text DEFAULT NULL COMMENT 'เหตุผลการขยายเวลา',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `project_value` decimal(15,2) DEFAULT NULL COMMENT 'มูลค่าโปรเจกต์ (บาท)',
  `payment_status` enum('pending','partial','paid','overdue') DEFAULT 'pending' COMMENT 'สถานะการชำระเงิน',
  `payment_terms` text DEFAULT NULL COMMENT 'เงื่อนไขการชำระเงิน',
  `actual_progress` tinyint(3) unsigned DEFAULT 0,
  `budget_hours` decimal(10,2) DEFAULT NULL,
  `actual_hours` decimal(10,2) DEFAULT NULL,
  `hourly_rate` decimal(10,2) DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `archived_at` datetime DEFAULT NULL COMMENT 'เก็บเข้าคลัง (ไม่แสดงในรายการปกติ)',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_projects_start_date` (`start_date`),
  KEY `idx_projects_end_date` (`end_date`),
  KEY `idx_projects_status` (`status`),
  KEY `idx_projects_deleted` (`deleted_at`),
  KEY `idx_projects_user_id` (`user_id`),
  KEY `idx_projects_company_id` (`company_id`),
  KEY `idx_projects_manager` (`manager_id`),
  KEY `idx_projects_tenant` (`tenant_id`),
  KEY `idx_kind` (`kind`),
  KEY `idx_archived_at` (`archived_at`),
  KEY `fk_projects_opportunity` (`opportunity_id`),
  CONSTRAINT `fk_projects_opportunity` FOREIGN KEY (`opportunity_id`) REFERENCES `sales_opportunities` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Projects and their metadata';
