INSERT INTO `quotation_templates` VALUES ('632a7fcc-a5f6-4dd5-b6af-3c1946a4cb4b','tenant-default','TCAC Document Tracking','','excel','uploads/quotation-templates/tenant-default/632a7fcc-a5f6-4dd5-b6af-3c1946a4cb4b.xls','application/vnd.ms-excel',NULL,'{\"headers\":[\"รหัส\",\"รายการสินค้า\",\"\",\"\",\"\",\"\",\"\",\"จำนวน\",\"\",\"ราคาต่อหน่วย\",\"\",\"\",\"ราคารวม\"],\"sample_rows\":[[\"KSSS\",\"KTN Solution Support Services\",null,null,null,null,null,null,null,null,null,null,null],[\"1\",\"บริการจดโดเมน Tcac.co.th \",null,null,null,null,null,\"1\",null,\"1000\",null,null,\"1000\"],[\"KSSS\",\"KTN Software Solution Services\",null,null,null,null,null,null,null,null,null,null,null],[\"2\",\"Microsoft 365 Business Basic [IMCSP-MS365BB-COM-Y]\",null,null,null,null,null,\"7\",null,\"1120\",null,null,\"7840\"],[\"KSSS\",\"KTN Solution Support Services\",null,null,null,null,null,null,null,null,null,null,null],[\"3\",\"KTN: Application Solution Support\",null,null,null,null,null,\"1\",null,\"80000\",null,null,\"80000\"],[null,\"App Name: Document Tracking Application\\nScope of Work\\/Reference: \\n- Creating and supporting a New Project for 1 Site on Document Tracking application\\n- Setting user names, groups, and e-mail addresses on New Project of Document Tracking application within 3 days only after we already created the new project (JERA-PT will have to inform us about user names and e-mail addresses for access and mail receiving)\\nDuration: 1 Weeks Approximately\\nNumber of Developer(s): 1-2 persons\\nDeveloper Level: Programmer or Programmer Analyst\\nReporting: Scope Completion or Status Updates\\nCustomer Coverage: Customer Head Office (Bangkok Areas)\\nWarranty: -\\n\\nNote: The service is not covered under other requirements or inapposite scopes\\n\",null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null]]}','[{\"item_name\":\"บริการจดโดเมน Tcac.co.th \",\"description\":\"\",\"quantity\":1,\"unit\":\"รายการ\",\"unit_price\":1000,\"total_price\":1000},{\"item_name\":\"Microsoft 365 Business Basic [IMCSP-MS365BB-COM-Y]\",\"description\":\"\",\"quantity\":7,\"unit\":\"รายการ\",\"unit_price\":1120,\"total_price\":7840},{\"item_name\":\"KTN: Application Solution Support\",\"description\":\"\",\"quantity\":1,\"unit\":\"รายการ\",\"unit_price\":80000,\"total_price\":80000},{\"item_name\":\"Cloud Server Fixed-Size R2\",\"description\":\"\",\"quantity\":12,\"unit\":\"รายการ\",\"unit_price\":15000,\"total_price\":180000}]',NULL,NULL,1,'e3b9b001-c686-4841-b03e-1583205f7beb','2026-05-20 00:49:10','2026-05-20 00:49:10'),('71192bef-3d0f-46f5-b09f-5d3de9fd60d6','tenant-default','Wowie MA Technical Support','','excel','uploads/quotation-templates/tenant-default/71192bef-3d0f-46f5-b09f-5d3de9fd60d6.xls','application/vnd.ms-excel',NULL,'{\"headers\":[\"รหัส\",\"รายการสินค้า\",\"\",\"\",\"\",\"\",\"\",\"จำนวน\",\"\",\"ราคาต่อหน่วย\",\"\",\"\",\"ราคารวม\"],\"sample_rows\":[[\"KMAS\",\"KTN Maintenance Services Support\",null,null,null,null,null,null,null,null,null,null,null],[null,\"KTN: 2026 DS Remote Support\",null,null,null,null,null,null,null,null,null,null,null],[\"1\",\"Local Support - Remote support 12 incidents\\/Year\",null,null,null,null,null,\"1\",null,\"180000\",null,null,\"180000\"],[null,\"Conditions: Technical support for 12 months\\n- Technical support via e-mail unlimited (8x5)\\n- Technical support via telephone will be limited to 2 callers per day (8x5)\\n- Technical support via remote IT services will use for Ad-hoc situation\\/emergency case will be limited to 12 incidents per Year (8x5)\\n- Technical support via on-site support will be limited to 6 times (8x5)\\n(1 on-site support day will provide up to 3-6 hours, and responding to you within 4 hours)\\n\\nScope of Our Services:\\n1.ให้คำปรึกษาและแก้ไขปัญหาอุปกรณ์ IT เช่น Access Point, Switch , MS365 , Printer , Computer\\n2.อุปกรณ์มี Client จำนวน 25 เครื่อง เป็น MacOS 20 , Window OS \\n3.กรณีมีเคส Support Onsite เดือนละ 6 ครั้ง\\/ปีหรือเคสที่ไม่สามารถ Remote ได้   \\n4.เวลา Service 8.00น. - 17.00น. (8x5)\\n\\nReporting:\\n- Reporting Troubleshooting Activities\\nStart by: Aug 1, 2026\\nExpires: July 1, 2027\\nLocation: Head Office (Quotation\'s Company Address)\\nCustomer Coverage: Remote Support\\n\\nNotices:\\n- KTN team will analyze incidents that it should be the on-site support or remote support\",null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null]]}','[{\"item_name\":\"Local Support - Remote support 12 incidents\\/Year\",\"description\":\"\",\"quantity\":1,\"unit\":\"รายการ\",\"unit_price\":180000,\"total_price\":180000}]',NULL,NULL,1,'e3b9b001-c686-4841-b03e-1583205f7beb','2026-05-17 07:32:08','2026-05-17 07:32:08'),('c532703d-78c1-4dfa-aefb-5f86c85307db','tenant-default','TCAC Microsoft Standard','','excel','uploads/quotation-templates/tenant-default/c532703d-78c1-4dfa-aefb-5f86c85307db.xls','application/vnd.ms-excel',NULL,'{\"headers\":[\"รหัส\",\"รายการสินค้า\",\"\",\"\",\"\",\"\",\"\",\"จำนวน\",\"\",\"ราคาต่อหน่วย\",\"\",\"\",\"ราคารวม\"],\"sample_rows\":[[\"KSSS\",\"KTN Software Solution Services\",null,null,null,null,null,null,null,null,null,null,null],[\"1\",\"Microsoft 365 Business Standard [IMCSP-MS365BS-COM-Y ]\",null,null,null,null,null,\"3\",null,\"3650\",null,null,\"10950\"],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null,null,null,null,null,null]]}','[{\"item_name\":\"Microsoft 365 Business Standard [IMCSP-MS365BS-COM-Y ]\",\"description\":\"\",\"quantity\":3,\"unit\":\"รายการ\",\"unit_price\":3650,\"total_price\":10950}]',NULL,NULL,1,'e3b9b001-c686-4841-b03e-1583205f7beb','2026-05-20 00:48:06','2026-05-20 00:48:06');
