CREATE TABLE `quotations` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `tenant_id` char(36) NOT NULL,
  `opportunity_id` char(36) DEFAULT NULL COMMENT 'FK to sales_opportunities',
  `company_id` char(36) NOT NULL COMMENT 'FK to companies',
  `customer_id` char(36) DEFAULT NULL COMMENT 'FK to customers (ผู้ติดต่อ)',
  `quotation_number` varchar(50) NOT NULL COMMENT 'เลขที่ใบเสนอราคา (QT-YYYYMM-0001)',
  `subject` varchar(255) DEFAULT '',
  `issue_date` date NOT NULL DEFAULT curdate() COMMENT 'วันที่ออกใบเสนอราคา',
  `valid_until` date NOT NULL COMMENT 'ใช้ได้ถึงวันที่',
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT 'ยอดรวมก่อนส่วนลด',
  `discount` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT 'ส่วนลด',
  `tax` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT 'ภาษี (VAT 7%)',
  `grand_total` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT 'ยอดรวมสุทธิ',
  `status` enum('draft','sent','approved','rejected','expired') NOT NULL DEFAULT 'draft' COMMENT 'สถานะใบเสนอราคา',
  `payment_terms` text DEFAULT '' COMMENT 'เงื่อนไขการชำระเงิน',
  `notes` text DEFAULT '' COMMENT 'หมายเหตุ',
  `created_by` char(36) NOT NULL COMMENT 'FK to users (ผู้สร้าง)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `quotation_number` (`quotation_number`),
  KEY `fk_quotations_customer` (`customer_id`),
  KEY `fk_quotations_user` (`created_by`),
  KEY `idx_quotations_opportunity` (`opportunity_id`),
  KEY `idx_quotations_company` (`company_id`),
  KEY `idx_quotations_status` (`status`),
  KEY `idx_quotations_created_at` (`created_at`),
  KEY `idx_quotations_tenant` (`tenant_id`),
  KEY `idx_quotations_customer` (`customer_id`),
  CONSTRAINT `fk_quotations_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_quotations_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_quotations_opportunity` FOREIGN KEY (`opportunity_id`) REFERENCES `sales_opportunities` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_quotations_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ตารางใบเสนอราคา';
