  `stage` enum('lead','qualified','proposal','negotiation','won','lost') NOT NULL DEFAULT 'lead' COMMENT 'ขั้นตอนการขาย',
  `value` decimal(15,2) NOT NULL DEFAULT 0.00 COMMENT 'มูลค่าโอกาส (บาท)',
  `probability` int(11) NOT NULL DEFAULT 0 COMMENT 'โอกาสความสำเร็จ (0-100%)',
  `expected_close_date` date DEFAULT NULL COMMENT 'วันที่คาดว่าจะปิดดีล',
  `actual_close_date` date DEFAULT NULL COMMENT 'วันที่ปิดดีลจริง',
  `assigned_to` char(36) NOT NULL COMMENT 'FK to users (ผู้รับผิดชอบ)',
  `created_by` char(36) DEFAULT NULL COMMENT 'FK to users (ผู้สร้าง lead)',
  `lead_source` varchar(100) DEFAULT '' COMMENT 'แหล่งที่มา (website, referral, etc.)',
  `competitor_info` text DEFAULT '' COMMENT 'ข้อมูลคู่แข่ง',
  `notes` text DEFAULT '' COMMENT 'บันทึกเพิ่มเติม',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_opportunities_company` (`company_id`),
  KEY `idx_opportunities_stage` (`stage`),
  KEY `idx_opportunities_assigned` (`assigned_to`),
  KEY `idx_opportunities_close_date` (`expected_close_date`),
  KEY `idx_opportunities_project` (`project_id`),
  KEY `idx_opportunities_expected_close_date` (`expected_close_date`),
  KEY `idx_opportunities_created_at` (`created_at`),
  KEY `idx_sales_opportunities_tenant` (`tenant_id`),
  KEY `idx_renewal_of` (`renewal_of`),
  KEY `idx_campaign_id` (`campaign_id`),
  CONSTRAINT `fk_opportunities_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_opportunities_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_opportunities_user` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_opportunity_campaign` FOREIGN KEY (`campaign_id`) REFERENCES `email_campaigns` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_opportunity_renewal` FOREIGN KEY (`renewal_of`) REFERENCES `sales_opportunities` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

