DROP TABLE IF EXISTS `support_contracts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `support_contracts` (
  `id` char(36) NOT NULL,
  `external_id` varchar(64) DEFAULT NULL COMMENT 'Domino @unid (migration source key)',
  `tenant_id` char(36) NOT NULL,
  `company_id` char(36) DEFAULT NULL,
  `customer_id` char(36) DEFAULT NULL,
  `contract_number` varchar(100) NOT NULL DEFAULT '',
  `title` varchar(255) NOT NULL,
  `description` text NOT NULL DEFAULT '',
  `type` enum('hardware','software','ma','support','other') NOT NULL DEFAULT 'support',
  `status` enum('active','expiring','expired','cancelled') NOT NULL DEFAULT 'active',
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `value` decimal(15,2) NOT NULL DEFAULT 0.00,
  `renewal_alert_days` int(11) NOT NULL DEFAULT 30,
  `vendor` varchar(255) NOT NULL DEFAULT '',
  `contact_name` varchar(255) NOT NULL DEFAULT '',
  `contact_phone` varchar(50) NOT NULL DEFAULT '',
  `contact_email` varchar(255) NOT NULL DEFAULT '',
  `notes` text NOT NULL DEFAULT '',
  `created_by` char(36) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sc_external_id` (`external_id`),
  KEY `idx_support_contracts_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

