  `type` enum('incident','request','problem','change') NOT NULL DEFAULT 'incident',
  `priority` enum('critical','high','medium','low') NOT NULL DEFAULT 'medium',
  `status` enum('open','in-progress','pending','resolved','closed') NOT NULL DEFAULT 'open',
  `channel` enum('phone','email','walk-in','line','system') NOT NULL DEFAULT 'system',
  `assigned_to` char(36) DEFAULT NULL,
  `task_id` char(36) DEFAULT NULL,
  `reported_by` varchar(255) NOT NULL DEFAULT '',
  `reporter_phone` varchar(50) NOT NULL DEFAULT '',
  `reporter_email` varchar(255) NOT NULL DEFAULT '',
  `resolution` text NOT NULL DEFAULT '',
  `sla_hours` int(11) NOT NULL DEFAULT 8,
  `first_response_at` datetime DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `csat_score` tinyint(4) DEFAULT NULL,
  `csat_comment` text NOT NULL DEFAULT '',
  `created_by` char(36) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `ai_suggested_json` longtext DEFAULT NULL CHECK (json_valid(`ai_suggested_json`)),
  `ai_suggested_at` datetime DEFAULT NULL,
  `resolution_note` text DEFAULT NULL COMMENT 'AI-generated resolution summary',
  `timesheet_id` char(36) DEFAULT NULL COMMENT 'Linked subtask (timesheet entry) created on ticket close',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ticket_number` (`ticket_number`),
  UNIQUE KEY `uq_st_external_id` (`external_id`),
  KEY `idx_support_tickets_tenant` (`tenant_id`),
  KEY `idx_support_tickets_task` (`task_id`),
  KEY `idx_st_tenant_status` (`tenant_id`,`status`),
  KEY `idx_st_tenant_assigned_created` (`tenant_id`,`assigned_to`,`created_at`),
  KEY `idx_st_tenant_priority_status` (`tenant_id`,`priority`,`status`),
  KEY `idx_support_tickets_company` (`company_id`),
  KEY `idx_support_tickets_contract` (`contract_id`),
  KEY `fk_tickets_project` (`project_id`),
  CONSTRAINT `fk_tickets_project` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
