b.Server )<br />\n    Dim body As NotesMIMEEntity<br />\n    session.ConvertMIME = False &#039; Do not convert MIME to rich text<br />\n    Set stream = session.CreateStream<br />\n    Dim child As NotesMIMEEntity<br />\n    Dim doc As NotesDocument<br />\n    Set doc = session.Documentcontext<br />\n    &#039;Begin creating the message doc to send <br />\n    Dim message As New NotesDocument (db)<br />\n    message.Form=&quot;memo&quot;<br />\n    Set body = message.CreateMIMEEntity<br />\n    Dim Principle As String<br />\n    Dim docconfig As NotesDocument<br />\n    <br />\n    <br />\n    Set docconfig = db.Getview(&quot;$vformConfiguration&quot;).Getfirstdocument()<br />\n    Principle = docconfig.config_value(0)<br />\n    <br />\n    message.ReplyTo = Principle &#039;<br />\n    message.Sender = Principle&#039;<br />\n    message.RecNoOutOfOffice = &quot;1&quot;   <br />\n    message.ReplyTo = Principle<br />\n    message.Sender = Principle<br />\n    message.Principal = |&quot;Memo Application&quot; &lt;| + Principle + |@nec.co.th&gt;|<br />\n    message.From = Principle<br />\n    message.AltFrom = Principle<br />\n    message.SendFrom = Principle<br />\n    message.INetFrom = Principle<br />\n    message.tmpDisplaySentBy = Principle<br />\n    message.tmpDisplayFrom_Preview = Principle<br />\n    message.DisplaySent = Principle    <br />\n    <br />\n    <br />\n    Dim xTask As String<br />\n    Dim xComment As String<br />\n    Dim sendto As Variant<br />\n    Dim xAction As string<br />\n    Dim nextApprover_Name As Variant<br />\n    Dim currentApprover As Variant<br />\n    Dim item As Variant<br />\n    Dim subject As String<br />\n    Dim xlfilename As String<br />\n    Dim xlfilename1 As String<br />\n    &#039;xAction = &quot;appr&quot; Then<br />\n    xTask = &quot;Approved&quot;<br />\n    xComment = doc.txtComment(0)<br />\n    doc.mm_meta = &quot;&quot;<br />\n    Set item =  doc.Replaceitemvalue(&quot;mm_approver_&quot; + Cstr(doc.mm_wait_for(0)) + &quot;_status&quot; , &quot;99&quot;)<br />\n    Set item =  doc.Replaceitemvalue(&quot;mm_approver_&quot; + Cstr(doc.mm_wait_for(0)) + &quot;_comment&quot; , xComment)<br />\n    Set item =  doc.Replaceitemvalue(&quot;mm_approver_&quot; + Cstr(doc.mm_wait_for(0)) + &quot;_date&quot; , Now)<br />\n    Dim mm_wait_for1 As Integer<br />\n    mm_wait_for1 = Cint(doc.mm_wait_for(0))+1<br />\n    currentApprover = doc.Getitemvalue(&quot;mm_approver_&quot; + CStr(doc.mm_wait_for(0)) + &quot;_name&quot;)<br />\n    Print &quot;currentApprover = &quot; &amp; currentApprover(0)<br />\n    nextApprover_Name  = doc.Getitemvalue(&quot;mm_approver_&quot; + Cstr(mm_wait_for1) + &quot;_name&quot;)<br />\n    If nextApprover_Name(0) = &quot;&quot; Then<br />\n        doc.mm_status = &quot;2&quot;<br />\n        doc.mm_wait_for = &quot;99&quot;<br />\n        sendto = doc.MM_FINAL_OPERATION<br />\n        xAction = &quot;Operation&quot;<br />\n    Else<br />\n        doc.mm_wait_for = Cstr(mm_wait_for1)<br />\n        sendto = nextApprover_Name(0)<br />\n        xAction = &quot;appr&quot;<br />\n    End If<br />\n    <br />\n    subject = doc.MM_ID(0) + &quot; : [&quot;+ doc.MM_GROUP(0) +&quot;]-[&quot;+ doc.MM_TITLE(0) +&quot;] is waiting for your action&quot;<br />\n    Dim files As Variant<br />\n    files = &quot;&quot;<br />\n    If doc.HasItem( &quot;post_upload&quot; ) Then    <br />\n        Dim rtitem As Variant<br />\n        Set rtitem = doc.Getfirstitem(&quot;post_upload&quot;)<br />\n        If ( rtitem.Type = RICHTEXT ) Then<br />\n            If doc.HasEmbedded Then<br />\n                Forall o In rtitem.EmbeddedObjects<br />\n                    files = files + o.Name + &quot;&lt;br&gt;&quot;<br />\n                End Forall<br />\n            End If<br />\n        End If    <br />\n    End If<br />\n    <br />\n    Print &quot;Case Approve&quot;<br />\n    Print &quot;Subject = &quot; &amp; subject<br />\n    &#039;Print &quot;Sendto = &quot; &amp; sendt