DROP TABLE IF EXISTS `task_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `task_history` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `task_id` char(36) NOT NULL COMMENT 'Which task changed',
  `action` enum('CREATED','UPDATED','STATUS_CHANGED','DEADLINE_SHIFTED','PAUSED','RESUMED','DELETED') NOT NULL COMMENT 'What happened',
  `field_name` varchar(100) DEFAULT NULL COMMENT 'Which field changed',
  `old_value` text DEFAULT NULL COMMENT 'Old value',
  `new_value` text DEFAULT NULL COMMENT 'New value',
  `changed_by` char(36) NOT NULL COMMENT 'Who made the change',
  `reason` text DEFAULT NULL COMMENT 'Why the change',
  `related_task_id` char(36) DEFAULT NULL COMMENT 'Related task (e.g., blocking task)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_task_history_task` (`task_id`),
  KEY `idx_task_history_changed_by` (`changed_by`),
  KEY `idx_task_history_related` (`related_task_id`),
  KEY `idx_task_history_action` (`action`),
  KEY `idx_task_history_created` (`created_at`),
  CONSTRAINT `fk_task_history_related` FOREIGN KEY (`related_task_id`) REFERENCES `tasks` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_task_history_task` FOREIGN KEY (`task_id`) REFERENCES `tasks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_task_history_user` FOREIGN KEY (`changed_by`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Audit trail for task changes';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `task_history`
--

LOCK TABLES `task_history` WRITE;
/*!40000 ALTER TABLE `task_history` DISABLE KEYS */;
