DROP TABLE IF EXISTS `task_validation_rules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `task_validation_rules` (
  `id` char(36) NOT NULL,
  `tenant_id` char(36) NOT NULL,
  `rule_type` enum('warn','block') NOT NULL,
  `condition_field` varchar(64) NOT NULL,
  `condition_operator` varchar(16) NOT NULL,
  `condition_value` varchar(255) DEFAULT NULL,
  `message_th` varchar(512) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_system` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` char(36) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `created_by` (`created_by`),
  KEY `idx_tvr_tenant` (`tenant_id`),
  KEY `idx_tvr_active` (`tenant_id`,`is_active`),
  CONSTRAINT `task_validation_rules_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `task_validation_rules_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

