--
-- Table structure for table `tasks`
--

DROP TABLE IF EXISTS `tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tasks` (
  `id` char(36) NOT NULL COMMENT 'UUID',
  `tenant_id` char(36) NOT NULL,
  `project_id` char(36) DEFAULT NULL COMMENT 'Parent project',
  `parent_task_id` char(36) DEFAULT NULL COMMENT 'Parent task for subtasks (null = root task)',
  `user_id` char(36) NOT NULL COMMENT 'Task creator',
  `title` varchar(255) NOT NULL COMMENT 'Task title',
  `description` text NOT NULL DEFAULT '' COMMENT 'Task description',
  `status` enum('pending','in-progress','completed','overdue','cancelled') NOT NULL DEFAULT 'pending' COMMENT 'Task status',
  `priority` enum('high','medium','low') NOT NULL DEFAULT 'medium' COMMENT 'Task priority',
  `assignee` varchar(255) NOT NULL DEFAULT '' COMMENT 'Person assigned to task',
  `assignee_user_id` char(36) DEFAULT NULL,
  `start_date` date NOT NULL DEFAULT curdate() COMMENT 'Task start date',
  `end_date` date NOT NULL COMMENT 'Task deadline',
  `original_end_date` date DEFAULT NULL COMMENT 'Original deadline (before shift)',
  `days_spent` int(11) NOT NULL DEFAULT 0 COMMENT 'Days actually spent',
  `estimated_days` int(11) NOT NULL DEFAULT 1 COMMENT 'Estimated days to complete',
  `is_ad_hoc` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Is this an ad-hoc/interruption task?',
  `task_type` varchar(50) NOT NULL DEFAULT 'task',
  `progress_percentage` tinyint(3) DEFAULT 0 COMMENT 'Progress percentage (0-100) auto-calculated from subtasks',
  `sort_order` int(11) DEFAULT 0 COMMENT 'Order within parent task',
  `is_subtask` tinyint(1) DEFAULT 0 COMMENT 'Is this a subtask?',
  `level` tinyint(2) DEFAULT 0 COMMENT 'Nesting level (0 = root, 1 = subtask, 2 = sub-subtask, etc.)',
  `completed_date` date DEFAULT NULL COMMENT 'Date when completed',
  `paused_at` datetime DEFAULT NULL COMMENT 'When task was paused',
  `paused_by` char(36) DEFAULT NULL COMMENT 'Who paused the task',
  `pause_reason` text DEFAULT NULL COMMENT 'Why task was paused',
  `delay_reason` text DEFAULT NULL COMMENT 'เหตุผลงานล่าช้า/เลื่อน',
  `auto_shifted` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Was timeline auto-shifted?',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `estimated_hours` decimal(6,2) DEFAULT NULL,
  `actual_hours` decimal(6,2) DEFAULT NULL,
  `base_actual_hours` decimal(6,2) DEFAULT NULL COMMENT 'Original manual hours before roll-up',
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `hourly_rate` decimal(10,2) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `recurring_task_id` char(36) DEFAULT NULL COMMENT 'Recurring template that generated this task',
