/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `cross_project_impact` AS select `td`.`id` AS `dependency_id`,`td`.`reason_code` AS `reason_code`,`td`.`impact_days` AS `impact_days`,`t_blocked`.`id` AS `blocked_task_id`,`t_blocked`.`title` AS `blocked_task_title`,`t_blocked`.`project_id` AS `blocked_project_id`,`p_blocked`.`name` AS `blocked_project_name`,`t_blocking`.`id` AS `blocking_task_id`,`t_blocking`.`title` AS `blocking_task_title`,`t_blocking`.`project_id` AS `blocking_project_id`,`p_blocking`.`name` AS `blocking_project_name`,`t_blocking`.`assignee` AS `assignee`,`td`.`created_at` AS `created_at`,`td`.`resolved_at` AS `resolved_at`,case when `td`.`resolved_at` is null then 1 else 0 end AS `is_active` from ((((`task_dependencies` `td` join `tasks` `t_blocked` on(`td`.`blocked_task_id` = `t_blocked`.`id`)) join `projects` `p_blocked` on(`t_blocked`.`project_id` = `p_blocked`.`id`)) join `tasks` `t_blocking` on(`td`.`blocking_task_id` = `t_blocking`.`id`)) join `projects` `p_blocking` on(`t_blocking`.`project_id` = `p_blocking`.`id`)) order by `td`.`created_at` desc */;
